create or replace function public.nail_2nya_available_dates(p_service_id uuid,p_from date default null,p_days integer default 28) returns table(available_date date,slots_count bigint) language sql security definer set search_path=public as $$ select d::date,count(s.slot_start)::bigint from generate_series(coalesce(p_from,current_date)::timestamp,(coalesce(p_from,current_date)+greatest(1,least(coalesce(p_days,28),60))-1)::timestamp,interval '1 day') d cross join lateral public.nail_2nya_available_slots(d::date,p_service_id) s group by d::date having count(s.slot_start)>0 order by d::date; $$; revoke all on function public.nail_2nya_available_dates(uuid,date,integer) from public; grant execute on function public.nail_2nya_available_dates(uuid,date,integer) to anon,authenticated;